import { test } from "@fast-check/vitest";
import fc from "fast-check";
import { describe, expect, it } from "vitest";
import { renderLocales, renderRegistry } from "../registry.js";

const HEADER =
  "// generated by wa — nie edytuj. Uruchom: npm run wa -- generate";
const BOTH = ["pl", "en"] as ("pl" | "en")[];

const base = {
  hasModuleTs: false,
  hasEnv: false,
  hasAuth: false,
  hasAuthClient: false,
  hasAuditSink: false,
  locales: [],
};

describe("renderRegistry", () => {
  it("emituje importy i tablice dla modułu z wszystkimi plikami", () => {
    const { server, client } = renderRegistry(
      [
        {
          name: "demo",
          hasModuleTs: true,
          hasEnv: true,
          hasAuth: true,
          hasAuthClient: true,
          hasAuditSink: false,
          locales: ["pl", "en"],
        },
      ],
      BOTH,
    );
    expect(
      server.startsWith(
        "// generated by wa — nie edytuj. Uruchom: npm run wa -- generate\n",
      ),
    ).toBe(true);
    expect(server).toContain(
      'import demoModule from "@/features/demo/module";',
    );
    expect(server).toContain(
      'import { envSchema as demoEnvSchema } from "@/features/demo/env";',
    );
    expect(server).toContain(
      'import { authPlugin as demoAuthPlugin } from "@/features/demo/auth";',
    );
    expect(server).toContain("export const modules = [demoModule];");
    expect(server).toContain(
      '{ key: "demo", load: () => import("@/features/demo/i18n/pl.json").then((m) => m.default) }',
    );
    expect(server).toContain('import("@/features/demo/i18n/en.json")');
    expect(
      client.startsWith(
        "// generated by wa — nie edytuj. Uruchom: npm run wa -- generate\n",
      ),
    ).toBe(true);
    expect(client).toContain(
      'import { authClientPlugin as demoAuthClientPlugin } from "@/features/demo/auth-client";',
    );
    expect(client).toContain(
      "export const authClientPlugins = [demoAuthClientPlugin];",
    );
    expect(client).toContain("export const clientModules = [demoModule];");
  });

  it("moduły bez plików dają puste tablice i puste locale", () => {
    const { server, client } = renderRegistry([{ name: "x", ...base }], BOTH);
    expect(server).toContain("export const modules: never[] = [];");
    expect(server).toContain("pl: [],");
    expect(client).toContain("export const clientModules: never[] = [];");
  });

  it("klient eksportuje pełne obiekty modułów, nie projekcję pól", () => {
    const { client } = renderRegistry(
      [
        { name: "a", ...base, hasModuleTs: true },
        { name: "b", ...base, hasModuleTs: true },
      ],
      BOTH,
    );
    expect(client).toContain(
      "export const clientModules = [aModule, bModule];",
    );
    expect(client).not.toContain("routePrefixes:");
  });

  it("nazwy z myślnikiem dają poprawne identyfikatory", () => {
    const { server } = renderRegistry(
      [{ name: "my-feature", ...base, hasModuleTs: true }],
      BOTH,
    );
    expect(server).toContain(
      'import myFeatureModule from "@/features/my-feature/module";',
    );
  });

  it("kolejność wejściowa jest zachowana", () => {
    const { server } = renderRegistry(
      [
        { name: "b", ...base, hasModuleTs: true },
        { name: "a", ...base, hasModuleTs: true },
      ],
      BOTH,
    );
    expect(server).toContain("export const modules = [bModule, aModule];");
  });
  const demo = {
    name: "demo",
    hasModuleTs: true,
    hasEnv: true,
    hasAuth: true,
    hasAuthClient: true,
    hasAuditSink: false,
    locales: ["pl", "en"],
  };

  it("serwer ma pełny kontrakt pliku dla modułu ze wszystkim", () => {
    expect(renderRegistry([demo], BOTH).server).toEqual(
      [
        "// generated by wa — nie edytuj. Uruchom: npm run wa -- generate",
        'import type { Locale } from "@/i18n/config";',
        'import demoModule from "@/features/demo/module";',
        'import { envSchema as demoEnvSchema } from "@/features/demo/env";',
        'import { authPlugin as demoAuthPlugin } from "@/features/demo/auth";',
        "",
        "export const modules = [demoModule];",
        "export const moduleEnvSchemas = [demoEnvSchema];",
        "export const authPlugins = [demoAuthPlugin];",
        "export const auditSinks: never[] = [];",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: [",
        '    { key: "demo", load: () => import("@/features/demo/i18n/pl.json").then((m) => m.default) },',
        "  ],",
        "  en: [",
        '    { key: "demo", load: () => import("@/features/demo/i18n/en.json").then((m) => m.default) },',
        "  ],",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("klient ma pełny kontrakt pliku dla modułu ze wszystkim", () => {
    expect(renderRegistry([demo], BOTH).client).toEqual(
      [
        "// generated by wa — nie edytuj. Uruchom: npm run wa -- generate",
        'import { authClientPlugin as demoAuthClientPlugin } from "@/features/demo/auth-client";',
        'import demoModule from "@/features/demo/module";',
        "",
        "export const authClientPlugins = [demoAuthClientPlugin];",
        "export const clientModules = [demoModule];",
        "",
      ].join("\n"),
    );
  });

  it("moduł bez env, auth i auth-client nie trafia do tych importów i tablic", () => {
    const { server, client } = renderRegistry(
      [
        demo,
        {
          name: "b",
          hasModuleTs: true,
          hasEnv: false,
          hasAuth: false,
          hasAuthClient: false,
          hasAuditSink: false,
          locales: [],
        },
      ],
      BOTH,
    );
    expect(server).not.toContain("@/features/b/env");
    expect(server).not.toContain("@/features/b/auth");
    expect(server).toContain(
      "export const moduleEnvSchemas = [demoEnvSchema];",
    );
    expect(server).toContain("export const authPlugins = [demoAuthPlugin];");
    expect(server).toContain("export const modules = [demoModule, bModule];");
    expect(client).not.toContain("@/features/b/auth-client");
    expect(client).toContain(
      "export const authClientPlugins = [demoAuthClientPlugin];",
    );
    expect(client).toContain(
      "export const clientModules = [demoModule, bModule];",
    );
  });

  it("kolejne separatory w nazwie daje jeden człon camelCase", () => {
    const { server } = renderRegistry(
      [{ name: "my--mod", ...base, hasModuleTs: true }],
      BOTH,
    );
    expect(server).toContain(
      'import myModModule from "@/features/my--mod/module";',
    );
    expect(server).toContain("export const modules = [myModModule];");
  });

  it("locales [pl] pomija klucz en i loadery en w pełnym pliku serwera", () => {
    expect(renderRegistry([demo], ["pl"]).server).toEqual(
      [
        HEADER,
        'import type { Locale } from "@/i18n/config";',
        'import demoModule from "@/features/demo/module";',
        'import { envSchema as demoEnvSchema } from "@/features/demo/env";',
        'import { authPlugin as demoAuthPlugin } from "@/features/demo/auth";',
        "",
        "export const modules = [demoModule];",
        "export const moduleEnvSchemas = [demoEnvSchema];",
        "export const authPlugins = [demoAuthPlugin];",
        "export const auditSinks: never[] = [];",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: [",
        '    { key: "demo", load: () => import("@/features/demo/i18n/pl.json").then((m) => m.default) },',
        "  ],",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("locales [pl] nie zmienia pliku klienta", () => {
    expect(renderRegistry([demo], ["pl"]).client).toEqual(
      renderRegistry([demo], BOTH).client,
    );
  });

  it("locales [pl] z modułem tylko z en daje pustą listę pl i brak en", () => {
    const { server } = renderRegistry(
      [{ name: "x", ...base, locales: ["en"] }],
      ["pl"],
    );
    expect(server).toContain("  pl: [],");
    expect(server).not.toContain("en:");
    expect(server).not.toContain("en.json");
  });

  it("locales [pl, en] emituje oba klucze, gdy żaden moduł nie ma tłumaczeń", () => {
    const { server } = renderRegistry([{ name: "x", ...base }], BOTH);
    expect(server).toContain("  pl: [],\n  en: [],\n};");
  });

  it("locales [en, pl] zachowuje kolejność z wejścia", () => {
    const { server } = renderRegistry([{ name: "x", ...base }], ["en", "pl"]);
    expect(server).toContain("  en: [],\n  pl: [],\n};");
  });

  it("renderLocales dla [pl] daje nagłówek i stałą as const", () => {
    expect(renderLocales(["pl"])).toBe(
      `${HEADER}\nexport const locales = ["pl"] as const;\n`,
    );
  });

  it("renderLocales dla [pl, en] daje nagłówek i stałą as const", () => {
    expect(renderLocales(["pl", "en"])).toBe(
      `${HEADER}\nexport const locales = ["pl", "en"] as const;\n`,
    );
  });

  it("moduł z audit-sink.ts daje import i tablicę auditSinks", () => {
    const { server } = renderRegistry(
      [{ name: "audit-logs", ...base, hasAuditSink: true }],
      BOTH,
    );
    expect(server.split("\n")).toContain(
      'import { auditSink as auditLogsAuditSink } from "@/features/audit-logs/audit-sink";',
    );
    expect(server.split("\n")).toContain(
      "export const auditSinks = [auditLogsAuditSink];",
    );
  });

  it("brak modułów z audit-sink.ts daje auditSinks jako never[]", () => {
    const { server } = renderRegistry([{ name: "x", ...base }], BOTH);
    expect(server.split("\n")).toContain(
      "export const auditSinks: never[] = [];",
    );
    expect(server).not.toContain("audit-sink");
  });

  it("moduł bez audit-sink.ts nie trafia do importów i tablicy auditSinks", () => {
    const { server } = renderRegistry(
      [
        { name: "audit-logs", ...base, hasAuditSink: true },
        { name: "b", ...base, hasModuleTs: true },
      ],
      BOTH,
    );
    expect(server).not.toContain("@/features/b/audit-sink");
    expect(server).not.toContain("bAuditSink");
    expect(server.split("\n")).toContain(
      "export const auditSinks = [auditLogsAuditSink];",
    );
  });

  it("dwa moduły z audit-sink.ts zachowują kolejność wejściową", () => {
    const { server } = renderRegistry(
      [
        { name: "alpha", ...base, hasAuditSink: true },
        { name: "beta", ...base, hasAuditSink: true },
      ],
      BOTH,
    );
    expect(server.split("\n")).toContain(
      "export const auditSinks = [alphaAuditSink, betaAuditSink];",
    );
    expect(server).toContain(
      'import { auditSink as alphaAuditSink } from "@/features/alpha/audit-sink";\nimport { auditSink as betaAuditSink } from "@/features/beta/audit-sink";',
    );
  });

  it("auditSinks nie trafia do pliku klienta", () => {
    const { client } = renderRegistry(
      [{ name: "audit-logs", ...base, hasModuleTs: true, hasAuditSink: true }],
      BOTH,
    );
    expect(client).not.toContain("audit-sink");
    expect(client).not.toContain("auditSinks");
    expect(client).not.toContain("AuditSink");
    expect(client).toBe(
      [
        HEADER,
        'import auditLogsModule from "@/features/audit-logs/module";',
        "",
        "export const authClientPlugins: never[] = [];",
        "export const clientModules = [auditLogsModule];",
        "",
      ].join("\n"),
    );
  });

  test.prop([fc.stringMatching(/^[a-z][a-z0-9]*([-_.][a-z0-9]+)*$/)])(
    "identyfikator importu modułu zawiera tylko znaki alfanumeryczne",
    (name) => {
      const { server } = renderRegistry(
        [{ name, ...base, hasModuleTs: true }],
        BOTH,
      );
      const importLine =
        server
          .split("\n")
          .find((line) => /^import \w+ from "@\/features\//.test(line)) ?? "";
      expect(importLine).toMatch(/^import [A-Za-z0-9]+Module from "/);
    },
  );
});
